import AppKit
import ScreenCaptureKit

struct ScreenCapture {
    /// Returns the display ID of the given screen, falling back to the main display.
    static func displayID(for screen: NSScreen) -> CGDirectDisplayID {
        let key = NSDeviceDescriptionKey("NSScreenNumber")
        return screen.deviceDescription[key] as? CGDirectDisplayID ?? CGMainDisplayID()
    }

    static func capture(displayID targetDisplayID: CGDirectDisplayID, scale: CGFloat) async -> NSImage? {
        let content: SCShareableContent
        do {
            content = try await SCShareableContent.excludingDesktopWindows(false, onScreenWindowsOnly: true)
        } catch {
            print("ScreenCapture: failed to get shareable content — \(error)")
            return nil
        }

        guard let display = content.displays.first(where: { $0.displayID == targetDisplayID }) else {
            print("ScreenCapture: display not found")
            return nil
        }

        let ownPID = ProcessInfo.processInfo.processIdentifier
        let excludedApps = content.applications.filter { $0.processID == ownPID }

        let filter = SCContentFilter(display: display, excludingApplications: excludedApps, exceptingWindows: [])

        let config = SCStreamConfiguration()
        config.width = Int(CGFloat(display.width) * scale)
        config.height = Int(CGFloat(display.height) * scale)
        config.scalesToFit = false
        config.showsCursor = false

        let cgImage: CGImage
        do {
            cgImage = try await SCScreenshotManager.captureImage(contentFilter: filter, configuration: config)
        } catch {
            print("ScreenCapture: capture failed — \(error)")
            return nil
        }

        let pointSize = NSSize(width: display.width, height: display.height)
        return NSImage(cgImage: cgImage, size: pointSize)
    }
}

import AppKit

final class AnnotationWindow: NSWindow {
    init(screen: NSScreen, screenshot: NSImage) {
        let maxRect = screen.frame.insetBy(
            dx: screen.frame.width * 0.08,
            dy: screen.frame.height * 0.08
        )

        let imageSize = screenshot.size
        let windowSize: NSSize
        if imageSize.width <= maxRect.width && imageSize.height <= maxRect.height {
            windowSize = imageSize
        } else {
            let scale = min(maxRect.width / imageSize.width, maxRect.height / imageSize.height)
            windowSize = NSSize(width: imageSize.width * scale, height: imageSize.height * scale)
        }

        let windowRect = NSRect(
            x: screen.frame.midX - windowSize.width / 2,
            y: screen.frame.midY - windowSize.height / 2,
            width: windowSize.width,
            height: windowSize.height
        )

        super.init(
            contentRect: windowRect,
            styleMask: .borderless,
            backing: .buffered,
            defer: false
        )
        self.level = .normal
        self.isOpaque = false
        self.backgroundColor = .clear
        self.hasShadow = true
        self.isReleasedWhenClosed = false
        self.collectionBehavior = [.canJoinAllSpaces, .fullScreenAuxiliary]
        self.contentView = AnnotationView(
            frame: NSRect(origin: .zero, size: windowRect.size),
            screenshot: screenshot
        )
    }

    override var canBecomeKey: Bool { true }
    override var canBecomeMain: Bool { true }
}

import AppKit
import Carbon.HIToolbox

// MARK: - Key Display Utilities

func carbonModifiers(from cocoa: NSEvent.ModifierFlags) -> UInt32 {
    var carbon: UInt32 = 0
    if cocoa.contains(.control) { carbon |= UInt32(controlKey) }
    if cocoa.contains(.option) { carbon |= UInt32(optionKey) }
    if cocoa.contains(.shift) { carbon |= UInt32(shiftKey) }
    if cocoa.contains(.command) { carbon |= UInt32(cmdKey) }
    return carbon
}

func cocoaModifiers(from carbon: UInt32) -> NSEvent.ModifierFlags {
    var flags = NSEvent.ModifierFlags()
    if carbon & UInt32(controlKey) != 0 { flags.insert(.control) }
    if carbon & UInt32(optionKey) != 0 { flags.insert(.option) }
    if carbon & UInt32(shiftKey) != 0 { flags.insert(.shift) }
    if carbon & UInt32(cmdKey) != 0 { flags.insert(.command) }
    return flags
}

func modifierSymbols(_ flags: NSEvent.ModifierFlags) -> String {
    var result = ""
    if flags.contains(.control) { result += "⌃" }
    if flags.contains(.option) { result += "⌥" }
    if flags.contains(.shift) { result += "⇧" }
    if flags.contains(.command) { result += "⌘" }
    return result
}

