override func mouseMoved(with event: NSEvent) {
    if case .editingText = interactionState { return }

    if isTextMode {
        NSCursor.iBeam.set()
        if hoveredAnnotationIndex != nil {
            hoveredAnnotationIndex = nil
            needsDisplay = true
        }
        return
    }

    updateHover(at: convert(event.locationInWindow, from: nil))
}

/// Re-evaluates hover state at the current mouse position. Call after the annotation
/// list changes without mouse movement (undo, redo, delete) so the hovered index isn't stale.
private func refreshHover() {
    guard let window, !isTextMode else { return }
    if case .editingText = interactionState { return }
    updateHover(at: convert(window.mouseLocationOutsideOfEventStream, from: nil))
}

private func updateHover(at viewPoint: CGPoint) {
    guard bounds.contains(viewPoint) else {
        if hoveredAnnotationIndex != nil {
